package com.example.battleshipgame.views;
import android.content.Intent;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.battleshipgame.Server;import com.example.battleshipgame.ui.Ui;
public class SettingsActivity extends AppCompatActivity {@Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=Ui.page(this);page.setGravity(Gravity.CENTER_HORIZONTAL);TextView eye=Ui.text(this,"SYSTEM SETTINGS",11,Ui.CYAN);eye.setLetterSpacing(.16f);Ui.spaced(page,eye,24);TextView title=Ui.text(this,"הגדרות",28,Ui.INK);title.setTypeface(null,1);Ui.spaced(page,title,4);Ui.spaced(page,Ui.card(this,"רמת יריב","חכם  •  לאחר פגיעה, המחשב מחפש במשבצות סמוכות."),30);Switch sound=new Switch(this);sound.setText("  צלילי משחק");sound.setTextSize(17);sound.setTextColor(Ui.INK);sound.setChecked(true);sound.setPadding(Ui.dp(this,18),Ui.dp(this,8),Ui.dp(this,18),Ui.dp(this,8));sound.setBackground(Ui.shape(Ui.PANEL,Ui.dp(this,18)));Ui.spaced(page,sound,12);Button back=Ui.button(this,"חזרה לתפריט",true);back.setOnClickListener(v->finish());Ui.spaced(page,back,28);Button logout=Ui.button(this,"⎋  התנתק מהחשבון",false);logout.setOnClickListener(v->{Server.auth(this).signOut();startActivity(new Intent(this,LoginActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();});Ui.spaced(page,logout,12);setContentView(page);}}
